// Auto-generated logo asset helper
import { ImageRun, Paragraph as DocxParagraph } from "docx";

export const LOGO_BASE64 = "";
export const LOGO_DATA_URL = "data:image/png;base64," + LOGO_BASE64;

export function getLogoUint8Array(): Uint8Array {
  const binaryString = atob(LOGO_BASE64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export function createDocxLogoHeader(w = 200, h = 82) {
  return new DocxParagraph({
    children: [
      new ImageRun({
        type: "png",
        data: getLogoUint8Array(),
        transformation: {
          width: w,
          height: h,
        },
      }),
    ],
  });
}
